// Request 1, Post-response
const json = pm.response.json();
pm.collectionVariables.set("orderId", json.json.orderId);
pm.test("orderId zapisany", function () {
  pm.expect(pm.collectionVariables.get("orderId")).to.eql("v123");
});

// Request 2, Post-response
pm.test("Drugi request dostał orderId", function () {
  pm.expect(pm.response.json().args.orderId).to.eql(pm.collectionVariables.get("orderId"));
});

pm.test("Drzewo kategorii to niepusta tablica", function () {
  const tree = pm.response.json();
  pm.expect(tree).to.be.an("array");
  pm.expect(tree).to.not.be.empty;
});
pm.test("Każda kategoria ma id i name", function () {
  pm.response.json().forEach(function (c) {
    pm.expect(c).to.have.property("id");
    pm.expect(c).to.have.property("name");
  });
});

const schema = {
  type: "array",
  items: {
    type: "object",
    required: ["id", "name"],
    properties: { id: { type: "number" }, name: { type: "string" } }
  }
};
pm.test("Drzewo zgodne ze schematem", function () {
  pm.response.to.have.jsonSchema(schema);
});
